results.text:
{
 "제목": "내 회사에 면접 보러 온 가해자들",
 "등장": [
  {
   "이름": "정원준",
   "모습_en": "An adult Korean man, age 28, with the same face as reference image 1. He has black hair with a blue streak. He is wearing a cheap, ill-fitting dark navy business suit and a loosened tie, exactly as shown in reference image 1."
  },
  {
   "이름": "편재현",
   "모습_en": "An adult Korean man, age 28, with the same face as reference image 2. He has wavy brown hair. He is wearing a neat black business suit with a white shirt and a dark tie, exactly as shown in reference image 2."
  },
  {
   "이름": "허성민",
   "모습_en": "An adult Korean man, age 28, with the same face as reference image 3. He has light blonde hair. He is wearing an all-black suit with a black shirt, unbuttoned at the collar, exactly as shown in reference image 3."
  },
  {
   "이름": "{유저}",
   "모습_en": "An adult of unspecified gender, seen only from behind or as close-ups of their hands. Their face is never visible. They wear a high-end, perfectly tailored, expensive business suit."
  }
 ],
 "페이지": [
  {
   "번호": 1,
   "요약": "과거, 지옥 같았던 괴롭힘의 기억이 어두운 복도를 배경으로 암시된다.",
   "칸": [
    {
     "설명": "{유저}의 시점. 바닥에 흩어진 책과 깨진 휴대폰이 보인다. 회상임을 알리는 검은 여백.",
     "내레이션": "지옥은 끝나지 않을 것 같았다.",
     "대사": [],
     "효과음": ""
    },
    {
     "설명": "책을 주우려는 떨리는 손 위로 운동화 발이 짓밟고 올라선다.",
     "내레이션": "",
     "대사": [],
     "효과음": "짓밟"
    },
    {
     "설명": "바닥에서 올려다본 구도. 얼굴이 보이지 않는 세 명의 가해자들이 섬뜩한 실루엣으로 서서 내려다본다.",
     "내레이션": "그들의 웃음소리가 귓가에 울렸다.",
     "대사": [],
     "효과음": ""
    }
   ],
   "prompt_en": "A vertical Korean webtoon page, in a semi-realistic 2D illustration style reminiscent of artists weifu and An Luchen, with clean line art, dramatic cel-shading, and a dark, oppressive color palette. The entire page has black gutters to signify a flashback. The page contains 3 panels stacked top to bottom. Panel 1: A first-person POV shot, looking down at scattered books and a shattered, unbranded smartphone on a dirty, dark hallway floor. A black rectangular narration caption box at the top contains the white Korean text \"지옥은 끝나지 않을 것 같았다.\". Panel 2: A close-up shot of a trembling adult hand trying to pick up a book from the floor. A foot wearing a worn-out sneaker forcefully steps on the hand. The Korean sound effect \"짓밟\" is written in a jagged font near the foot. Panel 3: A low-angle shot from the floor, looking up at three menacing, looming silhouettes of adult men against a harsh, blinding backlight. Their faces are completely obscured by shadow. One silhouette laughs silently. A black rectangular narration caption box at the bottom contains the white Korean text \"그들의 웃음소리가 귓가에 울렸다.\". Same characters throughout: The three silhouettes are adult men, their specific features are not visible. The hand on the floor belongs to an adult."
  },
  {
   "번호": 2,
   "요약": "과거의 고통을 딛고, {유저}가 성공을 위해 필사적으로 노력했던 날들을 보여주는 몽타주.",
   "칸": [
    {
     "설명": "밤늦게 책상 위, 손으로 필기하는 모습. 옆에는 에너지 드링크 캔들이 쌓여 있다.",
     "내레이션": "그래서, 도망쳤다.",
     "대사": [],
     "효과음": ""
    },
    {
     "설명": "어두운 사무실에서 노트북으로 작업하는 손. 화면에는 복잡한 그래프가 떠 있다.",
     "내레이션": "죽을힘을 다해서.",
     "대사": [],
     "효과음": ""
    },
    {
     "설명": "아침 햇살 속, {유저}가 세운 것으로 보이는 현대적인 고층 빌딩의 전경.",
     "내레이션": "마침내 모든 것을 내 손에 넣을 때까지.",
     "대사": [],
     "효과음": ""
    }
   ],
   "prompt_en": "A vertical Korean webtoon page, in a semi-realistic 2D illustration style with clean line art and full color. The page contains 3 panels stacked top to bottom separated by white gutters. Panel 1: A close-up shot of an adult's hand writing furiously on paper at a desk late at night, illuminated by a single desk lamp. A pile of unbranded energy drink cans is next to it. A black rectangular narration caption box contains the white Korean text \"그래서, 도망쳤다.\". Panel 2: A close-up on a pair of adult hands typing on a laptop in a dark office. The screen reflects complex financial graphs. A black rectangular narration caption box contains the white Korean text \"죽을힘을 다해서.\". Panel 3: A wide exterior shot of a modern, gleaming skyscraper against a bright morning sky. A black rectangular narration caption box at the bottom contains the white Korean text \"마침내 모든 것을 내 손에 넣을 때까지.\""
  },
  {
   "번호": 3,
   "요약": "성공한 대표가 된 현재, {유저}가 자신의 집무실에서 차가운 표정으로 도시를 내려다본다.",
   "칸": [
    {
     "설명": "{유저}의 뒷모습. 최고급 집무실의 통유리 창밖으로 펼쳐진 도시를 내려다보고 있다.",
     "내레이션": "모든 것을 손에 넣었지만,",
     "대사": [],
     "효과음": ""
    },
    {
     "설명": "유리창에 비친 {유저}의 실루엣. 표정은 보이지 않지만 차가운 분위기가 느껴진다.",
     "내레이션": "흉터는 사라지지 않았다.",
     "대사": [],
     "효과음": ""
    }
   ],
   "prompt_en": "A vertical Korean webtoon page, in a semi-realistic 2D illustration style with clean line art and realistic lighting. The page contains 2 panels stacked top to bottom separated by white gutters. Panel 1: A wide shot from behind an adult of unspecified gender, wearing a high-end, perfectly tailored business suit. They stand with hands clasped behind their back in a luxurious CEO's office, looking out a massive floor-to-ceiling window at a sprawling city below. A black rectangular narration caption box at the top right contains the white Korean text \"모든 것을 손에 넣었지만,\". Panel 2: A close-up on the person's reflection in the window. Their facial features are indistinct, forming a silhouette against the bright city, but the posture suggests a cold, hard demeanor. A black rectangular narration caption box at the bottom left contains the white Korean text \"흉터는 사라지지 않았다.\". Same character throughout: {유저} is an adult of unspecified gender, seen only from behind, wearing a high-end business suit."
  },
  {
   "번호": 4,
   "요약": "최종 면접 직전, {유저}가 면접자 명단에서 과거 가해자들의 이름을 발견하고 굳어진다.",
   "칸": [
    {
     "설명": "{유저}의 어깨 너머로 보이는 구도. 인사팀장이 태블릿을 들고 마지막 면접조에 대해 보고한다.",
     "내레이션": "",
     "대사": [
      {
       "누가": "인사팀장",
       "말": "대표님, 마지막 조입니다. 서류상으로는 아주 우수한 인재들입니다."
      }
     ],
     "효과음": ""
    },
    {
     "설명": "{유저}의 시점. 태블릿 화면에 '정원준, 편재현, 허성민'이라는 이름이 선명하게 보인다.",
     "내레이션": "결코 잊을 수 없는 이름들.",
     "대사": [],
     "효과음": ""
    },
    {
     "설명": "고급 만년필을 쥔 {유저}의 손 클로즈업. 펜을 쥔 손에 힘이 들어가 뼈마디가 하얗게 드러난다.",
     "내레이션": "",
     "대사": [],
     "효과음": "빠득."
    }
   ],
   "prompt_en": "A vertical Korean webtoon page, in a semi-realistic 2D illustration style with clean line art. The page contains 3 panels stacked top to bottom separated by white gutters. Panel 1: An over-the-shoulder shot of an adult CEO ({유저}) sitting at a large conference table. A generic adult HR manager stands beside them, briefing them while holding a tablet. A white rounded speech bubble with a tail pointing to the HR manager contains the Korean text \"대표님, 마지막 조입니다. 서류상으로는 아주 우수한 인재들입니다.\". Panel 2: First-person POV shot, looking at the tablet screen. A list of names under the heading '최종 면접 대상자' is visible. The names '정원준', '편재현', '허성민' are clearly displayed. A black rectangular narration caption box contains the white Korean text \"결코 잊을 수 없는 이름들.\". Panel 3: An extreme close-up on the CEO's hand gripping an expensive fountain pen tightly. The knuckles are white with tension. The Korean sound effect \"빠득.\" is written in a sharp font near the hand. Same characters throughout: {유저} is an adult of unspecified gender, seen from the shoulder or hands, wearing a high-end business suit. The HR Manager is a generic adult in business attire."
  },
  {
   "번호": 5,
   "요약": "면접실 밖, 정원준, 편재현, 허성민이 각기 다른 태도로 초조하게 대기하고 있다.",
   "칸": [
    {
     "설명": "면접실 복도에 선 세 남자. 정원준은 넥타이를 매만지고, 편재현은 안절부절못하며, 허성민은 고개를 숙이고 있다.",
     "내레이션": "",
     "대사": [],
     "효과음": ""
    },
    {
     "설명": "정원준 클로즈업. 억지로 자신감 있는 척하지만 식은땀을 흘린다.",
     "내레이션": "",
     "대사": [],
     "효과음": ""
    },
    {
     "설명": "편재현과 허성민. 편재현은 거의 울상이고, 허성민은 체념한 듯 바닥만 보고 있다.",
     "내레이션": "",
     "대사": [
      {
       "누가": "정원준",
       "말": "…정신 똑바로 차려라. 여기가 마지막 기회일지도 몰라."
      }
     ],
     "효과음": ""
    }
   ],
   "prompt_en": "A vertical Korean webtoon page, in a semi-realistic 2D illustration style with clean line art. The page contains 3 panels stacked top to bottom separated by white gutters. Panel 1: A medium shot of three adult men waiting anxiously in a modern office hallway. On the left, Jeong Wonjun nervously adjusts his crooked tie. In the center, Pyeon Jaehyeon fidgets. On the right, Heo Seongmin stares at the floor with his head bowed. Panel 2: A close-up on Jeong Wonjun's face. He has a strained, grim expression, trying to look confident, but a bead of sweat runs down his temple. Panel 3: A shot focusing on Pyeon Jaehyeon and Heo Seongmin. Pyeon Jaehyeon looks desperate. A white rounded speech bubble with a tail pointing to Jeong Wonjun (partially visible from the side) contains the Korean text \"…정신 똑바로 차려라. 여기가 마지막 기회일지도 몰라.\". Same characters throughout: Jeong Wonjun, an adult Korean man, age 28, with the same face as reference image 1, wearing the ill-fitting suit from ref 1. Pyeon Jaehyeon, an adult Korean man, age 28, with the same face as reference image 2, wearing the neat suit from ref 2. Heo Seongmin, an adult Korean man, age 28, with the same face as reference image 3, wearing the all-black suit from ref 3."
  },
  {
   "번호": 6,
   "요약": "마침내 면접실 문이 열리고, 아무것도 모르는 세 남자가 {유저}가 앉아있는 방으로 들어선다.",
   "칸": [
    {
     "설명": "대표 집무실의 육중한 문이 열리고, 직원이 그들을 안으로 안내한다.",
     "내레이션": "",
     "대사": [
      {
       "누가": "직원",
       "말": "지원자 정원준, 편재현, 허성민 님. 들어오십시오."
      }
     ],
     "효과음": "끼익…"
    },
    {
     "설명": "세로로 긴 칸. {유저}의 책상 너머에서 본 로우앵글. 방으로 들어서는 세 남자의 표정이 긴장에서 경악으로 변해가는 순간을 포착한다.",
     "내레이션": "",
     "대사": [],
     "효과음": ""
    },
    {
     "설명": "광택이 나는 어두운 책상 표면에 세 남자의 일그러진 얼굴이 비친다. 전경에는 '대표이사' 명패와 그 옆에 놓인 {유저}의 차분한 손이 보인다.",
     "내레이션": "",
     "대사": [
      {
       "누가": "{유저}",
       "말": "오랜만이네."
      }
     ],
     "효과음": ""
    }
   ],
   "prompt_en": "A vertical Korean webtoon page, in a semi-realistic 2D illustration style with dramatic lighting. The page contains 3 panels stacked top to bottom separated by white gutters. Panel 1: A shot of a large, opulent office door swinging open. A generic staff member gestures for the three men to enter. The Korean sound effect \"끼익…\" is written near the door hinge. A white rounded speech bubble with a tail pointing to the staff member contains the Korean text \"지원자 정원준, 편재현, 허성민 님. 들어오십시오.\". Panel 2: A long vertical panel. A low-angle shot from behind the CEO's desk, looking up at the three men as they walk in. Their expressions are captured in the process of shifting from nervous anticipation to dawning horror as they see the person in the CEO's chair (off-camera). Jeong Wonjun is in the lead, his eyes widening in disbelief. Panel 3: An extreme close-up stylistic shot. The distorted, shocked faces of the three men are reflected on the polished, dark surface of the CEO's desk. In the foreground, a calm adult hand rests next to a golden nameplate. The name on the plate is out of focus, but the title '대표이사' is clear. A white rounded speech bubble, its tail pointing towards the calm hand (implying the speaker is the CEO just off-panel), contains the Korean text \"오랜만이네.\" Same characters throughout: Jeong Wonjun (face ref 1, suit ref 1), Pyeon Jaehyeon (face ref 2, suit ref 2), Heo Seongmin (face ref 3, suit ref 3). The CEO's hand is visible."
  }
 ]
}
